using UnityEngine;

public class GameLogic : MonoBehaviour
{
    public PieceGenerator pieceGenerator;
    public int score;
    public int lives;

    private Piece[,] board;

    public void StartGame()
    {
        pieceGenerator.GenerateBoard();
        board = pieceGenerator.board;
    }

    public void SwapPieces(int x1, int y1, int x2, int y2)
    {
        Piece piece1 = board[x1, y1];
        Piece piece2 = board[x2, y2];

        if (piece1.type != PieceType.Empty && piece2.type != PieceType.Empty)
        {
            if (piece1.type == piece2.type)
            {
                // swap piezas
                Piece temp = piece1;
                piece1 = piece2;
                piece2 = temp;

                // check for matches
                CheckForMatches();
            }
        }
    }

    public void CheckForMatches()
    {
        for (int x = 0; x < boardWidth; x++)
        {
            for (int y = 0; y < boardHeight; y++)
            {
                Piece piece = board[x, y];

                if (piece.type != PieceType.Empty)
                {
                    // check for horizontal matches
                    if (x < boardWidth - 2)
                    {
                        if (piece.type == board[x + 1, y].type && piece.type == board[x + 2, y].type)
                        {
                            // remove matched pieces
                            RemovePieces(x, y, 3);
                        }
                    }

                    // check for vertical matches
                    if (y < boardHeight - 2)
                    {
                        if (piece.type == board[x, y + 1].type && piece.type == board[x, y + 2].type)
                        {
                            // remove matched pieces
                            RemovePieces(x, y, 3);
                        }
                    }
                }
            }
        }
    }

    public void RemovePieces(int x, int y, int count)
    {
        // remove pieces from the board
        for (int i = 0; i < count; i++)
        {
            board[x, y + i].type = PieceType.Empty;
        }

        // update score
        score += count * 10;

        // check for empty spaces
        CheckForEmptySpaces();
    }

    public void CheckForEmptySpaces()
    {
        // check for empty spaces and fill with new pieces
        for (int x = 0; x < boardWidth; x++)
        {
            for (int y = 0; y < boardHeight; y++)
            {
                Piece piece = board[x, y];

                if (piece.type == PieceType.Empty)
                {
                    // fill empty space with new piece
                    Piece newPiece = pieceGenerator.pieces[Random.Range(0, pieceGenerator.pieces.Length)];
                    board[x, y] = newPiece;
                }
            }
        }
    }
}
```
